import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        Membre m = new Membre(sc.nextLine());
        String ligne = sc.nextLine();
        while (!ligne.equals("fin")) {
            try {
                m.cotiser(Integer.parseInt(ligne.trim()));
            } catch (IllegalArgumentException e) {
                System.out.println("Refusé : " + ligne);
            }
            ligne = sc.nextLine();
        }
        System.out.println(m);
    }
}

class Membre {
    private String nom;
    private int total;

    Membre(String nom) {
        this.nom = nom;
    }

    void cotiser(int montant) {
        if (montant <= 0) {
            throw new IllegalArgumentException("montant invalide");
        }
        total += montant;
    }

    int getTotal() {
        return total;
    }

    @Override
    public String toString() {
        return nom + " : " + total + " FCFA";
    }
}
